/**
 * The concept glossary. Entries are short, plain-language definitions written in the same voice
 * as the lessons: say what the thing *does* before saying what it is called.
 */
export type GlossaryEntry = {
  id: string;
  term: string;
  short: string;
  /** Lesson where the concept is properly taught. */
  lesson?: string;
  aka?: string[];
  related?: string[];
};

export const GLOSSARY: GlossaryEntry[] = [
  { id: 'scalar', term: 'Scalar', short: 'A single number, like 3.7. The word exists mainly to contrast with vectors and matrices, which are collections of numbers.', lesson: 'vectors', related: ['vector'] },
  { id: 'vector', term: 'Vector', short: 'An ordered list of numbers. You can read it as data (a row of features) or as an arrow pointing somewhere in space — and much of machine learning works because both readings are true at once.', lesson: 'vectors', related: ['dot-product', 'dimension'] },
  { id: 'dimension', term: 'Dimension', short: 'How many numbers a vector contains. A 2D vector is a point on a page; a 768-dimensional vector is a point in a space we cannot picture but can still compute with exactly the same rules.', lesson: 'vectors' },
  { id: 'magnitude', term: 'Magnitude (length, norm)', short: 'How long a vector’s arrow is: the square root of the sum of its squared components. Pythagoras, generalised to any number of dimensions.', lesson: 'vectors', aka: ['norm', 'length'] },
  { id: 'dot-product', term: 'Dot product', short: 'Multiply two vectors element by element and add up the results. The answer is large and positive when the vectors point the same way, near zero when they are unrelated, and negative when they point in opposite directions.', lesson: 'dot-product', related: ['cosine-similarity', 'weighted-sum'] },
  { id: 'weighted-sum', term: 'Weighted sum', short: 'Multiply each input by how much it matters, then add everything up. It is the dot product of the inputs with a vector of weights, and it is the first thing every artificial neuron computes.', lesson: 'neuron', related: ['dot-product', 'weight'] },
  { id: 'cosine-similarity', term: 'Cosine similarity', short: 'The dot product of two vectors after shrinking both to length 1. It measures only direction: 1 means the same direction, 0 means perpendicular, −1 means opposite.', lesson: 'dot-product' },
  { id: 'orthogonal', term: 'Orthogonal', short: 'Perpendicular. Two vectors are orthogonal when their dot product is zero — knowing one tells you nothing about the other’s direction.', lesson: 'dot-product' },
  { id: 'matrix', term: 'Matrix', short: 'A grid of numbers. Read it as a table of data, or — more usefully — as a machine that transforms vectors: its columns record where each basis direction ends up.', lesson: 'matrices', related: ['linear-transformation', 'matrix-multiplication'] },
  { id: 'linear-transformation', term: 'Linear transformation', short: 'A way of moving every point in space that keeps grid lines straight, parallel and evenly spaced, and keeps the origin fixed. Every matrix is one, and every one is a matrix.', lesson: 'matrices' },
  { id: 'basis-vectors', term: 'Basis vectors', short: 'The unit arrows along each axis — in 2D, (1, 0) and (0, 1). Every vector is a combination of them, which is why knowing where a transformation sends them tells you where it sends everything.', lesson: 'matrices' },
  { id: 'determinant', term: 'Determinant', short: 'How much a transformation scales area (in 2D) or volume (in 3D). A determinant of 0 means space gets squashed flat, and information is lost for good.', lesson: 'matrices' },
  { id: 'matrix-multiplication', term: 'Matrix multiplication', short: 'A batch of dot products: each output entry is the dot product of a row of the first matrix with a column of the second. Geometrically, it composes two transformations into one.', lesson: 'matrix-multiplication' },
  { id: 'tensor', term: 'Tensor', short: 'In machine learning, simply an n-dimensional array of numbers with a shape like (batch, tokens, features). Scalars, vectors and matrices are tensors with 0, 1 and 2 dimensions.', lesson: 'matrix-multiplication' },
  { id: 'shape', term: 'Shape', short: 'The size of each dimension of a tensor, e.g. (32, 128, 768). Most bugs in ML code are shape bugs, and most architecture diagrams are really shape diagrams.', lesson: 'matrix-multiplication' },
  { id: 'broadcasting', term: 'Broadcasting', short: 'Array libraries’ rule for combining tensors of different shapes by implicitly repeating the smaller one along missing or size-1 dimensions — e.g. adding one bias vector to every row of a batch.', lesson: 'matrix-multiplication' },
  { id: 'function', term: 'Function', short: 'A rule that maps inputs to outputs. A neural network is one big function with millions of adjustable knobs.', lesson: 'derivatives' },
  { id: 'derivative', term: 'Derivative', short: 'How sensitive a function’s output is to a tiny nudge of its input: output change divided by input change, as the nudge shrinks toward zero. Geometrically, the slope of the graph at that point.', lesson: 'derivatives', related: ['gradient', 'chain-rule'] },
  { id: 'partial-derivative', term: 'Partial derivative', short: 'The derivative with respect to one input while holding all the other inputs fixed. A function with a million inputs has a million partial derivatives.', lesson: 'gradients' },
  { id: 'gradient', term: 'Gradient', short: 'The list of all partial derivatives of a function, packed into a vector. It points in the direction in which the output increases fastest; its negative points downhill.', lesson: 'gradients', related: ['gradient-descent'] },
  { id: 'chain-rule', term: 'Chain rule', short: 'When functions are chained together, their sensitivities multiply. If y changes 3× as fast as u, and u changes 2× as fast as x, then y changes 6× as fast as x.', lesson: 'chain-rule', related: ['backpropagation'] },
  { id: 'computational-graph', term: 'Computational graph', short: 'A diagram of a calculation as a network of simple operations, where edges carry values forward and gradients backward. Autodiff libraries build one every time you run a model.', lesson: 'backpropagation' },
  { id: 'probability-distribution', term: 'Probability distribution', short: 'A list of non-negative numbers, one per possible outcome, that add up to 1. A classifier’s output is a distribution over classes; a language model’s output is a distribution over its vocabulary.', lesson: 'probability' },
  { id: 'logits', term: 'Logits', short: 'The raw, unnormalised scores a model produces before softmax. They can be any real number; only their differences matter.', lesson: 'probability' },
  { id: 'softmax', term: 'Softmax', short: 'Turns a list of arbitrary scores into a probability distribution: exponentiate each score so it is positive, then divide by the total so they sum to 1. Bigger scores get disproportionately more probability.', lesson: 'probability', related: ['logits', 'temperature'] },
  { id: 'temperature', term: 'Temperature', short: 'A number that divides the logits before softmax. Low temperature sharpens the distribution toward the top choice; high temperature flattens it toward uniform.', lesson: 'probability' },
  { id: 'logarithm', term: 'Logarithm', short: 'The inverse of exponentiation: log₂(8) = 3 because 2³ = 8. Logs turn multiplication into addition and squash huge ranges into manageable ones.', lesson: 'information' },
  { id: 'surprise', term: 'Surprise (information content)', short: 'How surprising an outcome is: −log(p). Certain events carry 0 surprise; a 1-in-1024 event carries 10 bits.', lesson: 'information' },
  { id: 'entropy', term: 'Entropy', short: 'The average surprise of a distribution — how uncertain it is. A fair coin has 1 bit of entropy; a coin that always lands heads has 0.', lesson: 'information' },
  { id: 'cross-entropy', term: 'Cross-entropy loss', short: 'How surprised a model was by the correct answer: −log of the probability it assigned to it. Confident and right costs almost nothing; confident and wrong costs a great deal.', lesson: 'information', related: ['softmax', 'loss'] },
  { id: 'mean', term: 'Mean (average)', short: 'Add the values up and divide by how many there are. It is the balance point of the data: equal weights placed at each value would balance there. One extreme value can drag it a long way; the median (the middle value) resists.', lesson: 'statistics', aka: ['average', 'expected value'], related: ['variance'] },
  { id: 'variance', term: 'Variance', short: 'The average squared distance from the mean: how spread out a set of numbers is, in squared units. Its great property is that for independent quantities, variances add, which is why the spread of an average shrinks like 1/√n.', lesson: 'statistics', related: ['standard-deviation', 'mean', 'standard-error'] },
  { id: 'standard-deviation', term: 'Standard deviation (SD, σ)', short: 'The square root of the variance: a typical distance from the mean, in the data’s own units. For a bell-shaped quantity, about 68% of values lie within ±1 SD of the mean and about 95% within ±2.', lesson: 'statistics', aka: ['SD', 'sigma'], related: ['variance', 'normal-distribution'] },
  { id: 'normal-distribution', term: 'Normal distribution (bell curve)', short: 'The symmetric bell-shaped distribution that sums of many independent pieces approach, whatever the pieces look like (the central limit theorem). Fully described by its mean and standard deviation.', lesson: 'statistics', aka: ['bell curve', 'Gaussian', 'central limit theorem'], related: ['standard-deviation'] },
  { id: 'standard-error', term: 'Standard error', short: 'The standard deviation of an average: σ/√n for n independent measurements. It is how much a measured score (an accuracy, a mean loss, a mini-batch gradient) would wobble if you repeated the measurement on fresh data. Halving it takes 4× the data.', lesson: 'statistics', related: ['variance', 'mini-batch'] },
  { id: 'curse-of-dimensionality', term: 'Curse of dimensionality', short: 'The ways high-dimensional spaces defy low-dimensional intuition: volume concentrates near surfaces and in corners, random directions are nearly perpendicular, and distances from a point to random others all become almost equal. Real data escapes much of it by having structure.', lesson: 'high-dimensions', related: ['cosine-similarity', 'superposition'] },
  { id: 'superposition', term: 'Superposition', short: 'Storing more features than there are dimensions (or neurons) by giving each feature its own nearly perpendicular direction and tolerating a little interference. Possible because high-dimensional spaces hold far more nearly perpendicular directions than exactly perpendicular ones.', lesson: 'high-dimensions', related: ['curse-of-dimensionality', 'cosine-similarity'] },
  { id: 'neuron', term: 'Artificial neuron', short: 'A tiny function: multiply each input by a weight, add them up with a bias, then pass the result through an activation function.', lesson: 'neuron', related: ['weight', 'bias', 'activation-function'] },
  { id: 'weight', term: 'Weight', short: 'A learned number that controls how strongly one input influences a neuron. Positive weights push the output up, negative weights push it down.', lesson: 'neuron' },
  { id: 'bias', term: 'Bias', short: 'A learned number added to a neuron’s weighted sum. It shifts the neuron’s threshold, letting its decision boundary move away from the origin.', lesson: 'neuron' },
  { id: 'decision-boundary', term: 'Decision boundary', short: 'The surface in input space where a classifier switches from one answer to another. For a single neuron it is a straight line (or flat plane).', lesson: 'neuron' },
  { id: 'perceptron', term: 'Perceptron', short: 'A single threshold unit that learns its own weights: when it gets an example wrong, it adds the input to its weights (or subtracts it). It always succeeds when a straight line can separate the classes, and never when one can’t.', lesson: 'perceptron', related: ['linearly-separable', 'neuron'] },
  { id: 'credit-assignment', term: 'Credit assignment problem', short: 'Working out which part of a system deserves the credit, or the blame, for its output. For a network with hidden neurons: how should each hidden weight change, when only the final answer is known to be wrong? Backpropagation is the answer for networks.', lesson: 'perceptron', related: ['backpropagation'] },
  { id: 'linearly-separable', term: 'Linearly separable', short: 'A dataset whose classes can be split perfectly by a single straight line (or flat hyperplane). XOR is the classic example of data that is not.', lesson: 'activation-functions' },
  { id: 'activation-function', term: 'Activation function', short: 'The non-linear function applied after a neuron’s weighted sum. Without it, any stack of layers collapses into a single linear transformation.', lesson: 'activation-functions', related: ['relu', 'sigmoid'] },
  { id: 'relu', term: 'ReLU', short: 'Rectified Linear Unit: max(0, x). Negative inputs become zero, positive inputs pass through unchanged. Absurdly simple, and the default activation for a decade of deep learning.', lesson: 'activation-functions' },
  { id: 'sigmoid', term: 'Sigmoid', short: 'An S-shaped curve squashing any number into (0, 1). Handy for probabilities, but its slope nearly vanishes for large inputs, which slows learning in deep networks.', lesson: 'activation-functions' },
  { id: 'gelu', term: 'GELU', short: 'A smooth cousin of ReLU, x·Φ(x), used in BERT and GPT-style transformers. It lets slightly negative values leak through rather than cutting them off sharply.', lesson: 'activation-functions' },
  { id: 'loss', term: 'Loss function', short: 'A single number measuring how wrong a model is on some data. Training means adjusting the parameters to make this number smaller.', lesson: 'loss-functions', aka: ['cost', 'objective'], related: ['mse', 'mae', 'cross-entropy'] },
  { id: 'gradient-descent', term: 'Gradient descent', short: 'Repeatedly nudge every parameter a small step in the direction that reduces the loss — the negative gradient. The step size is the learning rate.', lesson: 'gradient-descent', related: ['learning-rate', 'gradient'] },
  { id: 'learning-rate', term: 'Learning rate', short: 'How big a step gradient descent takes. Too small and training crawls; too large and it overshoots, oscillates, or diverges entirely.', lesson: 'gradient-descent' },
  { id: 'parameter', term: 'Parameter', short: 'Any number the model learns during training — weights and biases. A “7B model” has about seven billion of them.', lesson: 'neuron' },
  { id: 'backpropagation', term: 'Backpropagation', short: 'An efficient way to compute the gradient of the loss with respect to every parameter, by applying the chain rule backwards through the computational graph, reusing work as it goes.', lesson: 'backpropagation', related: ['chain-rule', 'computational-graph'] },
  { id: 'autodiff', term: 'Automatic differentiation', short: 'Software that records the operations of a calculation and then computes exact derivatives by running the chain rule over that record. PyTorch and JAX are built around it.', lesson: 'backpropagation', aka: ['autograd'] },
  { id: 'forward-pass', term: 'Forward pass', short: 'Running an input through the network layer by layer — each layer weighs the previous layer’s outputs, adds its biases and applies its activation — to get an answer. During training the intermediate values are kept, because the backward pass needs them.', lesson: 'forward-propagation', related: ['layer', 'backward-pass'] },
  { id: 'layer', term: 'Layer', short: 'A group of neurons that all read the same inputs and work independently of each other. Because of that independence, a whole layer is one matrix multiplication (plus biases and an activation). Layers between the input and the output are called hidden layers.', lesson: 'forward-propagation', aka: ['hidden layer', 'dense layer', 'fully connected layer'], related: ['neuron', 'forward-pass'] },
  { id: 'mse', term: 'Mean squared error (MSE)', short: 'The average of the squared errors. Squaring makes big errors count disproportionately — like springs that pull harder the more they stretch — so its best constant guess is the mean, and outliers drag it around.', lesson: 'loss-functions', aka: ['squared error', 'L2 loss'], related: ['mae', 'loss'] },
  { id: 'mae', term: 'Mean absolute error (MAE)', short: 'The average size of the errors, ignoring sign. Every error pulls with the same strength, so its best constant guess is the median, and a few wild outliers barely move it.', lesson: 'loss-functions', aka: ['absolute error', 'L1 loss'], related: ['mse', 'loss'] },
  { id: 'mini-batch', term: 'Mini-batch', short: 'A small random sample of the training data used to estimate the gradient for one step — a poll of the dataset. Its error shrinks like one over the square root of its size.', lesson: 'sgd-minibatch', aka: ['batch size'], related: ['sgd', 'epoch'] },
  { id: 'sgd', term: 'Stochastic gradient descent (SGD)', short: 'Gradient descent where each step uses a gradient estimated from a random mini-batch instead of the whole dataset. Many cheap, slightly noisy steps beat a few exact ones.', lesson: 'sgd-minibatch', related: ['mini-batch', 'gradient-descent'] },
  { id: 'epoch', term: 'Epoch', short: 'One full pass through the training data. With mini-batches of size B, an epoch is about N ÷ B steps.', lesson: 'sgd-minibatch', related: ['mini-batch'] },
  { id: 'momentum', term: 'Momentum', short: 'An optimizer trick: keep a running velocity of recent gradients and step along it. Consistent slopes add up (about 10× with β = 0.9) while alternating ones cancel, which cures zig-zagging in narrow valleys.', lesson: 'optimizers', related: ['adam', 'gradient-descent'] },
  { id: 'adam', term: 'Adam / AdamW', short: 'The default optimizer for large models: momentum plus a per-weight step size scaled by the root of recent squared gradients (as in RMSProp), with a start-up correction. AdamW adds weight decay separately. Costs two extra numbers per weight.', lesson: 'optimizers', aka: ['RMSProp', 'AdamW'], related: ['momentum'] },
  { id: 'lr-schedule', term: 'Learning-rate schedule', short: 'A plan for changing the step size during training — big steps early for fast progress, small steps late so mini-batch noise doesn’t leave the model jittering. Common shapes: step decay, cosine decay, and warmup followed by decay.', lesson: 'lr-schedules', aka: ['cosine decay', 'warmup'], related: ['learning-rate', 'sgd'] },
  { id: 'overfitting', term: 'Overfitting', short: 'When a model fits its training data — noise and all — so closely that it does worse on new data. The tell-tale sign: training loss keeps falling while test loss rises.', lesson: 'overfitting', related: ['test-set', 'underfitting', 'bias-variance'] },
  { id: 'test-set', term: 'Test set', short: 'Examples held back from training and used only to measure how well the model does on data it has never seen. Training accuracy measures fit; test accuracy measures whether the pattern was learned.', lesson: 'training-lab', aka: ['held-out data'], related: ['overfitting', 'validation-set'] },
  { id: 'underfitting', term: 'Underfitting', short: 'When a model is too stiff to follow the pattern in the data, so it is wrong on the training examples and on new ones by about the same amount. The fix is more capacity or better inputs, not more data.', lesson: 'overfitting', related: ['overfitting', 'capacity'] },
  { id: 'generalization', term: 'Generalisation', short: 'How well a model does on data it was not trained on. It is the only thing that really matters: you already know the answers for your training examples.', lesson: 'overfitting', aka: ['generalization'], related: ['overfitting', 'test-set'] },
  { id: 'capacity', term: 'Capacity', short: 'How flexible a family of models is: roughly, how many different patterns it could fit. More coefficients, neurons, layers or training steps mean more capacity. Too little underfits; too much, for the amount of data, overfits.', lesson: 'overfitting', related: ['underfitting', 'overfitting'] },
  { id: 'bias-variance', term: 'Bias–variance trade-off', short: 'Expected error on new data = bias² (how wrong the average fit is) + variance (how much fits from different training sets disagree) + noise. More capacity lowers bias and raises variance.', lesson: 'overfitting', related: ['overfitting', 'underfitting'] },
  { id: 'regularization', term: 'Regularisation', short: 'Any change to training that deliberately gives up a little fit on the training data to do better on new data — usually by preferring simpler explanations of the data. Early stopping, weight decay and dropout are the most common.', lesson: 'regularization', aka: ['regularization'], related: ['overfitting', 'weight-decay', 'dropout', 'early-stopping'] },
  { id: 'early-stopping', term: 'Early stopping', short: 'Watch the validation error during training, remember the weights whenever it reaches a new best, and stop once it has not improved for a while (the patience). The remembered weights are the result.', lesson: 'regularization', related: ['regularization', 'validation-set'] },
  { id: 'weight-decay', term: 'Weight decay (L2 regularisation)', short: 'Adding λ/2 · Σw² to the loss, so large weights cost something. Each gradient step then shrinks every weight by a factor (1 − ηλ) before the usual update, and only weights the data keeps pushing survive.', lesson: 'regularization', aka: ['L2 regularisation', 'L2 penalty', 'ridge'], related: ['regularization'] },
  { id: 'dropout', term: 'Dropout', short: 'During training, switch off each hidden neuron at random with probability p (a fresh choice every step) and scale the survivors up by 1/(1 − p); at test time use every neuron. It stops neurons relying on fragile partnerships.', lesson: 'regularization', related: ['regularization'] },
  { id: 'data-leakage', term: 'Data leakage', short: 'When information from the test data (or from the future) sneaks into training — for example, test examples that are copies of training examples. The test score then measures memory rather than generalisation, and looks far better than real-world performance.', lesson: 'diagnosis-lab', aka: ['leakage'], related: ['test-set', 'overfitting'] },
  { id: 'gradient-check', term: 'Gradient check', short: 'Testing a hand-written backward pass by nudging each weight a tiny amount, measuring how much the loss changes, and comparing that measured slope with the computed gradient. Essential, because a wrong gradient often still trains.', lesson: 'network-from-scratch', aka: ['numerical gradient check'], related: ['backpropagation'] },
  { id: 'attention', term: 'Attention', short: 'A soft dictionary lookup: each word’s query is scored against every word’s key (a dot product), softmax turns the scores into shares, and the output is the values blended in those shares. softmax(QKᵀ/√d)·V — a weighted sum whose weights are computed from the input itself.', lesson: 'attention', aka: ['self-attention', 'scaled dot-product attention'], related: ['dot-product', 'softmax'] },
  { id: 'multi-head-attention', term: 'Multi-head attention', short: 'Several attention heads run side by side, each with its own queries, keys and values (and its own softmax budget), so each word can look for several things at once. Their outputs are concatenated and mixed by W_O. With the width fixed, more heads cost nothing extra.', lesson: 'multi-head-attention', aka: ['attention heads'], related: ['attention'] },
  { id: 'rope', term: 'Rotary position embedding (RoPE)', short: 'Giving attention a sense of order by rotating each query and key by an angle proportional to its position, with many rotation speeds. The score between two words then depends on their contents and their offset, not on where in the text they sit.', lesson: 'positions', aka: ['RoPE', 'rotary embeddings'], related: ['attention'] },
  { id: 'transformer', term: 'Transformer', short: 'The architecture behind modern language models: token embeddings plus position information, then a stack of identical blocks (layer norm → attention → add; layer norm → feed-forward network → add), then an output layer.', lesson: 'transformer-block', related: ['attention', 'residual-connection', 'layer-norm'] },
  { id: 'residual-connection', term: 'Residual connection', short: 'Adding a sublayer’s output to its input (x + f(x)) instead of replacing it. Every layer annotates a shared “residual stream”, and the learning signal always has a direct path back, so very deep stacks stay trainable.', lesson: 'transformer-block', aka: ['skip connection', 'residual stream'], related: ['transformer'] },
  { id: 'layer-norm', term: 'Layer norm', short: 'For each token’s vector separately: subtract its mean, divide by its spread, then apply a learned scale and shift. Keeps each sublayer’s inputs at a predictable size however large the residual stream grows.', lesson: 'transformer-block', aka: ['layer normalisation', 'LayerNorm'], related: ['transformer'] },
  { id: 'causal-mask', term: 'Causal mask', short: 'Setting every attention score from a token to a later token to −∞ before the softmax, so each token sees only itself and earlier tokens. Without it, next-token training could cheat by copying the answer.', lesson: 'transformer-block', aka: ['attention mask'], related: ['attention'] },
  { id: 'tokenization', term: 'Tokenisation', short: 'Chopping raw text into pieces (subwords) and mapping each piece to an integer ID so a model can look up its embedding vector. Balances sequence length against vocabulary size.', lesson: 'tokenization', aka: ['tokenization', 'subword tokenisation', 'token'], related: ['bpe', 'transformer'] },
  { id: 'bpe', term: 'Byte-pair encoding (BPE)', short: 'A subword tokeniser that starts from single characters (or the 256 raw UTF-8 bytes) and repeatedly merges the most frequent adjacent pair into a new token, then encodes new text by replaying those merges in order.', lesson: 'tokenization', aka: ['BPE', 'byte-level BPE'], related: ['tokenization'] },
  { id: 'language-model', term: 'Language model', short: 'A model that assigns a probability distribution to the next token given the tokens so far. Minimising cross-entropy across huge text corpora forces it to learn syntax, facts and structure.', lesson: 'next-token-prediction', aka: ['LLM', 'large language model'], related: ['autoregressive', 'perplexity'] },
  { id: 'autoregressive', term: 'Autoregressive generation', short: 'Generating a sequence one token at a time: predict a probability distribution for the next token, pick one, append it to the prompt, and feed the longer sequence back in.', lesson: 'next-token-prediction', related: ['language-model', 'causal-mask'] },
  { id: 'perplexity', term: 'Perplexity', short: 'exp(average cross-entropy loss) — the effective branching factor of a language model. Perplexity 15 means the model is, on average, as uncertain as rolling a fair 15-sided die. Lower is better; 1 is perfect.', lesson: 'next-token-prediction', aka: ['PPL'], related: ['cross-entropy', 'entropy', 'language-model'] },
  { id: 'top-k', term: 'Top-k sampling', short: 'Keep only the k highest-probability next tokens, zero out the rest of the vocabulary, and re-normalise before drawing. Simple, but forces the exact same pool size on both sharp factual prompts and wide-open ones.', lesson: 'sampling', related: ['top-p', 'temperature'] },
  { id: 'top-p', term: 'Top-p (nucleus) sampling', short: 'Sort next-token probabilities from largest to smallest, keep the smallest prefix whose cumulative probability reaches at least p (e.g. 0.90), and sample from that “nucleus”. Automatically narrows when confident and widens when uncertain.', lesson: 'sampling', aka: ['nucleus sampling'], related: ['top-k', 'temperature'] },
  { id: 'beam-search', term: 'Beam search', short: 'Deterministic decoding that keeps the top B highest-probability partial sequences alive at every step rather than committing greedily to only the #1 token. Finds much higher-probability whole sentences than greedy decoding.', lesson: 'sampling', related: ['autoregressive'] },
  { id: 'scaling-law', term: 'Scaling law', short: 'An empirical power-law relationship predicting a model’s cross-entropy loss from its parameter count N, training tokens D and compute C ≈ 6ND. Lets labs forecast huge training runs from small experiments.', lesson: 'scaling-laws', related: ['chinchilla-optimal', 'perplexity'] },
  { id: 'chinchilla-optimal', term: 'Chinchilla-optimal training', short: 'Allocating a fixed training compute budget C ≈ 6ND by scaling parameters and training tokens roughly equally (~20 tokens per parameter), minimising training FLOPs for a target loss. Inference-heavy deployments deliberately over-train smaller models far past this ratio.', lesson: 'scaling-laws', aka: ['compute-optimal training'], related: ['scaling-law'] },
  { id: 'bf16', term: 'BF16 (bfloat16)', short: 'Brain Float 16: a 16-bit float with 1 sign bit, 8 exponent bits (the exact range of FP32, up to 3.4 × 10³⁸) and 7 mantissa bits. Replaced FP16 for training because it avoids 65,504 overflows and gradient underflow.', lesson: 'quantization', aka: ['bfloat16'], related: ['quantization'] },
  { id: 'quantization', term: 'Quantisation', short: 'Storing model weights (and sometimes activations or KV caches) in fewer bits — e.g. INT8 or INT4 instead of FP32/BF16 — using per-group scale factors to shrink memory and speed up memory-bound decoding.', lesson: 'quantization', aka: ['quantization', 'INT4', 'INT8'], related: ['bf16', 'memory-bound'] },
  { id: 'kv-cache', term: 'KV cache', short: 'Saving every past token’s Key and Value vectors in GPU memory during autoregressive decoding so each new token computes only one row of attention instead of reprocessing the whole conversation. Exact memoisation, not an approximation.', lesson: 'kv-cache', aka: ['key–value cache'], related: ['causal-mask', 'gqa', 'memory-bound'] },
  { id: 'gqa', term: 'Grouped-Query Attention (GQA)', short: 'Sharing a smaller number of Key and Value heads across groups of Query heads (e.g. 8 KV heads for 32 or 64 Q heads in Llama-3), shrinking the KV cache 4×–8× with minimal quality loss.', lesson: 'kv-cache', aka: ['GQA', 'MQA', 'multi-query attention'], related: ['multi-head-attention', 'kv-cache'] },
  { id: 'memory-bound', term: 'Memory-bandwidth bound', short: 'When a GPU spends most of its time waiting to stream weights and KV caches out of VRAM rather than doing maths. Single-user LLM decoding (~1 FLOP/byte vs H100’s 295 FLOP/byte ridge) leaves over 99% of Tensor Cores idle.', lesson: 'kv-cache', aka: ['roofline', 'arithmetic intensity'], related: ['kv-cache', 'quantization'] },
  { id: 'vanishing-gradients', term: 'Vanishing & exploding gradients', short: 'Because backprop multiplies local derivatives layer by layer, signals in deep networks either decay exponentially to zero (freezing early layers, e.g. 0.25¹⁶ ≈ 10⁻¹⁰ in Sigmoid) or explode to NaN when weights are too large.', lesson: 'vanishing-gradients', aka: ['exploding gradients'], related: ['backpropagation', 'xavier-init', 'he-init', 'residual-connection'] },
  { id: 'xavier-init', term: 'Xavier / Glorot initialisation', short: 'Drawing initial weights with standard deviation σ = 1/√d_in (or √(2/(d_in + d_out))) so linear or small-signal tanh layers preserve activation variance of 1 across depth.', lesson: 'vanishing-gradients', aka: ['Glorot initialisation'], related: ['he-init', 'vanishing-gradients'] },
  { id: 'he-init', term: 'He / Kaiming initialisation', short: 'Drawing initial weights with standard deviation σ = √(2/d_in) for ReLU layers. The extra √2 compensates for ReLU zeroing out the negative half of pre-activations, keeping variance equal to 1.', lesson: 'vanishing-gradients', aka: ['Kaiming initialisation'], related: ['xavier-init', 'relu', 'vanishing-gradients'] },
  { id: 'lora', term: 'LoRA (Low-Rank Adaptation)', short: 'Freezing a pretrained model’s weights W₀ and learning a low-rank update ΔW = (α/r)·B·A where B starts at zero and A starts random. Cuts trainable parameters and Adam states by >100×, and merges into W₀ with zero inference overhead.', lesson: 'lora', aka: ['low-rank adaptation'], related: ['qlora', 'adam'] },
  { id: 'qlora', term: 'QLoRA', short: 'LoRA applied on top of a frozen 4-bit quantised base model: stores the base weights in ~4.5 bits while training small BF16/FP32 adapters, cutting Llama-3 70B fine-tuning VRAM from ~1,052 GiB down to ~40 GiB.', lesson: 'lora', related: ['lora', 'quantization'] },
  { id: 'rlhf', term: 'RLHF (Reinforcement Learning from Human Feedback)', short: 'Aligning an LLM by training a proxy reward model on pairwise human preferences, then optimising the policy to maximise proxy reward minus a KL-divergence penalty β·D_KL(π ‖ π_ref) that keeps it close to the SFT reference.', lesson: 'rlhf-dpo', related: ['dpo', 'reward-hacking'] },
  { id: 'dpo', term: 'DPO (Direct Preference Optimisation)', short: 'Rewriting KL-regularised RLHF in closed form so the partition function Z(x) cancels out, turning preference alignment into a single supervised classification loss −log σ(β·ln(π/π_ref)_w − β·ln(π/π_ref)_l) with no separate reward model.', lesson: 'rlhf-dpo', related: ['rlhf', 'reward-hacking'] },
  { id: 'reward-hacking', term: 'Reward hacking (Goodhart’s law)', short: 'When an optimiser finds a way to earn the reward that isn’t what the designer meant: farming a renewable bonus, gaming a measurement, or exploiting an imperfect reward model (raising proxy score while true quality falls). The reward was the bug, not the optimiser.', lesson: 'reward-hacking', aka: ['specification gaming', 'over-optimisation', 'Goodhart’s law'], related: ['rlhf', 'dpo', 'reward-shaping'] },
  { id: 'validation-set', term: 'Validation set', short: 'Held-out examples used to choose settings — model size, step size, when to stop — so that the test set can stay untouched for one final, honest measurement.', lesson: 'overfitting', aka: ['dev set'], related: ['test-set'] },
  { id: 'feature-engineering', term: 'Feature engineering', short: 'Hand-crafting the inputs a model receives so the problem becomes easy for it — like giving a single neuron x² and y² so a circle becomes a straight-line cut. Hidden layers learn features like these automatically.', lesson: 'training-lab' },
  { id: 'ablation', term: 'Ablation', short: 'Switching part of a model off — a neuron, a layer, an attention head, a whole component — and measuring what gets worse. It answers “what does this part contribute?”, though redundant parts can each look unimportant on their own.', lesson: 'network-playground', related: ['dead-neuron'] },
  { id: 'dead-neuron', term: 'Dead neuron', short: 'A ReLU neuron whose tally is negative for every input, so it always outputs zero. Its slope is zero too, so training can never revive it. Leaky ReLU and careful initialisation reduce the risk.', lesson: 'network-playground', aka: ['dying ReLU'], related: ['relu', 'ablation'] },
  { id: 'batch', term: 'Batch', short: 'Several inputs processed together, stacked as the rows of a matrix so the same weights meet all of them in one big matrix multiplication. GPUs are much faster on one large multiplication than on many small ones.', lesson: 'forward-propagation', related: ['tensor', 'shape'] },
  { id: 'backward-pass', term: 'Backward pass', short: 'Walking the computational graph from the loss back to the inputs, computing how sensitive the loss is to every intermediate value and parameter.', lesson: 'backpropagation' },
  { id: 'mdp', term: 'Markov Decision Process (MDP)', short: 'The formal model of sequential decision-making: states S, actions A, transition probabilities P(s′|s,a), rewards R, and a discount factor γ. “Markov” means the current state holds everything that matters for predicting the future.', lesson: 'mdps', aka: ['MDP'], related: ['policy', 'discount-factor', 'bellman-equation'] },
  { id: 'policy', term: 'Policy (π)', short: 'An agent’s strategy: a rule mapping each state to an action (deterministic) or a probability distribution over actions (stochastic). The optimal policy π* maximises expected discounted return from every state.', lesson: 'mdps', related: ['mdp', 'value-function'] },
  { id: 'discount-factor', term: 'Discount factor (γ)', short: 'A number in [0, 1) that multiplies each step of future reward: a reward k steps away counts for γᵏ. Controls the agent’s planning horizon (~1/(1−γ) steps) and keeps infinite-horizon returns finite.', lesson: 'mdps', aka: ['gamma', 'discounting'], related: ['mdp', 'bellman-equation'] },
  { id: 'value-function', term: 'Value function (V, Q)', short: 'The expected discounted return starting from a state V(s) — or from a state–action pair Q(s, a) — assuming you follow a policy thereafter. Summarises the entire future in a single cached number.', lesson: 'mdps', aka: ['state value', 'action value'], related: ['bellman-equation', 'policy'] },
  { id: 'bellman-equation', term: 'Bellman equation', short: 'The recursive self-consistency law of value functions: a state’s optimal value equals the best action’s expected immediate reward plus γ times the optimal value of wherever you land next.', lesson: 'mdps', aka: ['Bellman optimality equation'], related: ['value-iteration', 'value-function'] },
  { id: 'value-iteration', term: 'Value Iteration', short: 'Dynamic programming for solving an MDP when transitions P and rewards R are known: repeatedly sweep Bellman optimality updates across all states until values stop changing.', lesson: 'mdps', related: ['bellman-equation', 'mdp'] },
  { id: 'exploration-exploitation', term: 'Exploration vs exploitation', short: 'The core dilemma of learning by trial and error: cash in on the best option you have found so far (exploit), or try uncertain options that might turn out even better (explore).', lesson: 'q-learning', related: ['q-learning'] },
  { id: 'td-learning', term: 'Temporal-Difference (TD) learning', short: 'Updating a value estimate using a one-step lookahead target (r + γV(s′)) rather than waiting for the episode to end. The gap between that target and the old estimate is the TD error δ.', lesson: 'q-learning', aka: ['TD error', 'bootstrapping'], related: ['q-learning', 'sarsa', 'bellman-equation'] },
  { id: 'q-learning', term: 'Q-learning', short: 'Model-free, off-policy TD control: learn action-values Q(s,a) directly from experience via Q ← Q + α(r + γ max Q(s′,a′) − Q). Lets an agent act via argmax Q without knowing transition probabilities.', lesson: 'q-learning', related: ['sarsa', 'td-learning', 'off-policy'] },
  { id: 'sarsa', term: 'SARSA', short: 'On-policy TD control (State–Action–Reward–State–Action): updates Q(s,a) using the value Q(s′,a′) of the action the agent actually takes next, pricing in its own exploration risk.', lesson: 'q-learning', related: ['q-learning', 'td-learning', 'off-policy'] },
  { id: 'off-policy', term: 'Off-policy vs on-policy', short: 'An on-policy algorithm (like SARSA) evaluates the same exploratory policy it uses to act. An off-policy algorithm (like Q-learning) follows an exploratory behaviour policy while learning the value of a different target policy (usually greedy).', lesson: 'q-learning', aka: ['on-policy'], related: ['q-learning', 'sarsa'] },
  { id: 'policy-gradient', term: 'Policy gradient (REINFORCE)', short: 'Learning a policy directly: sample an action, then push its probability up or down in proportion to how well it went, Δθ = α(G − b)∇log π(a|s). Needs no model of the environment and no max over actions, so it works for huge or continuous action spaces and for stochastic policies.', lesson: 'policy-gradients', aka: ['REINFORCE', 'score-function estimator', 'log-derivative trick'], related: ['advantage', 'actor-critic', 'ppo'] },
  { id: 'advantage', term: 'Advantage', short: 'How much better an action turned out than what the policy usually gets from that situation: the return minus a baseline, or the TD error r + γV(s′) − V(s). It is the number that should scale a policy-gradient push; subtracting a state-only baseline adds no bias but can slash variance.', lesson: 'policy-gradients', aka: ['baseline', 'advantage function'], related: ['policy-gradient', 'actor-critic'] },
  { id: 'actor-critic', term: 'Actor-critic', short: 'A policy (the actor) trained alongside a value estimate (the critic). Each step is judged by the critic’s TD error δ = r + γV(s′) − V(s), which contains one step’s noise instead of a whole episode’s — a little bias for much lower variance.', lesson: 'policy-gradients', related: ['advantage', 'td-learning', 'policy-gradient'] },
  { id: 'ppo', term: 'PPO (Proximal Policy Optimisation)', short: 'A policy-gradient method that reuses each batch for several epochs but clips the probability ratio π_new/π_old to [1 − ε, 1 + ε] in the direction the advantage pushes, so no single batch can drag the policy far. The workhorse of deep RL and of the original RLHF pipeline.', lesson: 'policy-gradients', aka: ['proximal policy optimization', 'clipped surrogate'], related: ['policy-gradient', 'rlhf'] },
  { id: 'reward-shaping', term: 'Reward shaping', short: 'Adding extra reward to speed up learning when the real reward is sparse. A naive bonus (e.g. “+k for being close”) can become a goal in itself; a potential-based bonus γΦ(s′) − Φ(s) provably never changes which behaviour is best (Ng, Harada & Russell, 1999).', lesson: 'reward-hacking', aka: ['potential-based shaping', 'shaping bonus'], related: ['reward-hacking', 'q-learning'] },
  { id: 'xor', term: 'XOR', short: '“Exclusive or”: true when exactly one of two inputs is true. Famous in ML because no single straight line can separate its true cases from its false ones.', lesson: 'activation-functions' },
  { id: 'generative-model', term: 'Generative model', short: 'A model that produces new examples resembling its training data (new faces, sentences, sounds) rather than answering a question about an input. Language models, VAEs, GANs and diffusion models are all generative.', lesson: 'autoencoders', related: ['vae', 'autoencoder'] },
  { id: 'autoencoder', term: 'Autoencoder', short: 'A pair of networks trained together: an encoder squeezes each input into a short code, and a decoder rebuilds the input from the code. The narrow code forces it to discover the few factors that explain the data.', lesson: 'autoencoders', related: ['latent-space', 'vae'] },
  { id: 'latent-space', term: 'Latent space', short: 'The space of codes a model uses internally to describe its data: “latent” means hidden. In a good latent space, nearby codes mean similar things and the directions correspond to real factors, like smile or eye openness.', lesson: 'autoencoders', aka: ['latent', 'code space'], related: ['autoencoder'] },
  { id: 'vae', term: 'Variational autoencoder (VAE)', short: 'An autoencoder whose encoder outputs a fuzzy region (a centre and a spread) instead of an exact code, and is charged (with a KL term) for regions that differ from the standard bell. Then decoding random standard-bell codes generates new examples.', lesson: 'autoencoders', aka: ['VAE'], related: ['kl-divergence', 'reparameterization-trick', 'posterior-collapse'] },
  { id: 'kl-divergence', term: 'KL divergence', short: 'A measure of how different one probability distribution is from another: the extra surprise you suffer, on average, by expecting the second when the truth is the first. Zero only when they match. It is the leash in RLHF and the pull towards the bell in a VAE.', lesson: 'information', aka: ['KL', 'Kullback–Leibler divergence'], related: ['cross-entropy', 'vae'] },
  { id: 'reparameterization-trick', term: 'Reparameterisation trick', short: 'Writing a random sample as code = centre + spread × fresh noise, so the randomness sits in the noise and gradients can flow through the centre and spread. It is what makes VAEs trainable with backpropagation.', lesson: 'autoencoders', aka: ['reparameterisation trick'], related: ['vae'] },
  { id: 'posterior-collapse', term: 'Posterior collapse', short: 'A VAE failure where the pull towards the standard bell wins: every input gets the same code, the code carries no information, and the decoder can only draw one average output.', lesson: 'autoencoders', related: ['vae'] },
  { id: 'diffusion-model', term: 'Diffusion model', short: 'A generator that learns to reverse a noising process: data is gradually dissolved into random noise, and a network learns to remove a little noise at a time, so new examples can be made by starting from pure noise and denoising step by step.', lesson: 'diffusion', aka: ['diffusion', 'DDPM'], related: ['denoiser', 'ddim', 'noise-schedule'] },
  { id: 'denoiser', term: 'Denoiser', short: 'The network at the heart of a diffusion model. Given a noisy input and its noise level, it predicts the noise (equivalently, its best guess of the clean input). Trained with squared error, it learns the average of everything that could have produced the noisy input.', lesson: 'diffusion', related: ['diffusion-model'] },
  { id: 'ddim', term: 'DDIM', short: 'A deterministic way to sample a diffusion model: at each stop, guess the clean input, work out the noise that guess implies, and rebuild at a lower noise level with that same noise. It can skip most of the training schedule’s steps without retraining.', lesson: 'diffusion', related: ['diffusion-model', 'noise-schedule'] },
  { id: 'noise-schedule', term: 'Noise schedule', short: 'How quickly the signal share falls as noise is added in a diffusion model, and, when sampling, which noise levels the sampler stops at. Where the stops go matters as much as how many there are.', lesson: 'diffusion', related: ['diffusion-model', 'ddim'] },
  { id: 'conditioning', term: 'Conditioning', short: 'Giving a generative model an extra input that says what to make (a class, a text prompt, a sketch), so it learns the distribution of data given that input. In a diffusion model, the denoiser reads the condition and its best guess averages only over matching data.', lesson: 'guidance', related: ['classifier-free-guidance', 'diffusion-model'] },
  { id: 'classifier-free-guidance', term: 'Classifier-free guidance (CFG)', short: 'A way to steer a diffusion model harder towards its prompt: take the unconditional prediction and move w times the difference the prompt makes. w = 1 is plain conditioning; larger w gives more typical, on-prompt samples at the cost of variety.', lesson: 'guidance', aka: ['CFG', 'guidance scale', 'guidance'], related: ['conditioning'] },
  { id: 'rag', term: 'Retrieval-augmented generation (RAG)', short: 'Answering from documents by searching them first: find the passages most relevant to the question, paste them into the prompt, and ask the model to answer from them. Only as good as its retrieval.', lesson: 'rag', aka: ['RAG', 'retrieval'], related: ['embedding', 'cosine-similarity'] },
  { id: 'embedding', term: 'Embedding', short: 'A dense vector that represents the meaning of a symbol, word, or image, learned so similar meanings sit close together in geometry. Compared with cosine similarity, embeddings enable zero-shot transfer and semantic search.', lesson: 'one-hot-vs-dense', aka: ['embeddings', 'embedding model'], related: ['one-hot-encoding', 'embedding-table', 'cosine-similarity', 'rag'] },
  { id: 'tool-calling', term: 'Tool calling (function calling)', short: 'A protocol where a language model emits a structured request (usually JSON) naming a tool and arguments; your host code validates and executes the real function and pastes the result back into the prompt.', lesson: 'tool-calling', aka: ['function calling'], related: ['agent-loop', 'structured-outputs'] },
  { id: 'structured-outputs', term: 'Structured outputs (constrained decoding)', short: 'Forcing a language model to emit text matching a JSON grammar or schema by masking out illegal next tokens before softmax. Guarantees syntax and types, never business rules or database invariants.', lesson: 'tool-calling', aka: ['constrained decoding', 'JSON mode'], related: ['tool-calling'] },
  { id: 'agent-loop', term: 'Agent loop', short: 'The repeated cycle behind AI agents: send the transcript and tool schemas to the model, parse and validate any emitted tool call, execute it in your host code, append the observation, and repeat until the model emits a final answer or hits a step cap.', lesson: 'tool-calling', aka: ['ReAct loop', 'AI agent'], related: ['tool-calling', 'structured-outputs'] },
  { id: 'paired-eval', term: 'Paired evaluation (McNemar’s test)', short: 'Scoring two models on the exact same frozen test questions so shared easy/hard items cancel out, then judging only the disagreements (A-only wins vs B-only wins) against a fair coin.', lesson: 'evaluation', aka: ['McNemar’s test', 'paired comparison'], related: ['statistical-power', 'standard-error'] },
  { id: 'eval-overfitting', term: 'Eval overfitting (winner’s curse)', short: 'Trying many prompts or settings on the same small eval set and keeping the highest score: selection picks whichever run got luckiest on that set, producing a mirage that vanishes on fresh held-out data.', lesson: 'evaluation', aka: ['winner’s curse', 'benchmark overfitting'], related: ['overfitting', 'validation-set'] },
  { id: 'llm-as-a-judge', term: 'LLM-as-a-judge', short: 'Using a language model to grade or compare open-ended outputs where exact matching fails. Scales cheaply, but suffers from position bias (cured by swapping order), verbosity bias, and signal attenuation (2q − 1).', lesson: 'evaluation', aka: ['model-graded eval'], related: ['paired-eval', 'statistical-power'] },
  { id: 'statistical-power', term: 'Statistical power', short: 'The probability an evaluation detects a real improvement of a given size Δ without missing it. Grows with sample size n, paired comparisons, and grader accuracy q; shrinks when you tighten the false-positive cap α.', lesson: 'evaluation', aka: ['detection power'], related: ['paired-eval', 'standard-error'] },
  { id: 'normal-equations', term: 'Normal equations', short: 'The exact one-shot algebraic solution to linear and Ridge regression: w* = (XᵀX + λI)⁻¹Xᵀy. Skips gradient descent altogether, though collinear features make XᵀX ill-conditioned unless λ > 0.', lesson: 'linear-regression', aka: ['OLS closed form', 'ordinary least squares'], related: ['weight-decay', 'mse'] },
  { id: 'logistic-regression', term: 'Logistic regression', short: 'A convex linear classifier that models log-odds linearly and squashes them through a sigmoid into calibrated probabilities p = σ(w·x + b), trained with cross-entropy so easy far-out points don’t distort the boundary.', lesson: 'linear-regression', aka: ['log-odds model'], related: ['sigmoid', 'cross-entropy', 'roc-auc'] },
  { id: 'precision-recall', term: 'Precision and recall', short: 'Two complementary classification metrics for imbalanced data: precision = TP/(TP+FP) (“when the alarm rings, how often is it real?”) and recall = TP/(TP+FN) (“what share of all real positives did we catch?”).', lesson: 'linear-regression', aka: ['F1 score', 'confusion matrix'], related: ['roc-auc', 'logistic-regression'] },
  { id: 'roc-auc', term: 'ROC curve & AUC', short: 'A plot of True Positive Rate (recall) against False Positive Rate as you sweep a classifier’s decision threshold from 1 to 0. Its area (AUC, from 0.5 random to 1.0 perfect) measures ranking quality independently of any single threshold.', lesson: 'linear-regression', aka: ['AUC', 'AUROC', 'ROC'], related: ['precision-recall', 'logistic-regression'] },
  { id: 'knn', term: 'k-Nearest Neighbours (kNN)', short: 'A lazy, non-parametric algorithm that stores the training set verbatim and predicts a new point by letting its k closest training neighbours vote (uniformly or weighted by 1/d). Sensitive to feature scales and irrelevant noise columns.', lesson: 'knn', aka: ['kNN', 'nearest neighbours'], related: ['feature-scaling', 'curse-of-dimensionality'] },
  { id: 'feature-scaling', term: 'Feature scaling (standardisation)', short: 'Rescaling each input feature to mean 0 and SD 1 using training-set statistics only: z = (x − μ)/σ. Essential for distance-based methods (kNN, k-means) and gradient descent so wide-range units don’t swamp narrow ones.', lesson: 'knn', aka: ['z-score normalisation', 'standardisation'], related: ['knn', 'standard-deviation'] },
  { id: 'decision-tree', term: 'Decision tree (CART)', short: 'A model that classifies or predicts by asking a tree of axis-aligned yes/no threshold questions (“x₁ ≤ 5.19?”). Invariant to monotone feature scaling and naturally skips irrelevant columns, though deep single trees overfit easily.', lesson: 'decision-trees', aka: ['CART'], related: ['gini-impurity', 'random-forest', 'gradient-boosting'] },
  { id: 'gini-impurity', term: 'Gini impurity', short: 'How mixed a tree node’s classes are: G = 2p(1 − p) for binary classes (0 = pure, 0.5 = 50/50 mix). Greedy CART trees pick whichever feature and threshold reduces weighted child Gini impurity the most.', lesson: 'decision-trees', related: ['decision-tree', 'entropy'] },
  { id: 'random-forest', term: 'Random Forest (bagging)', short: 'An ensemble of many deep decision trees trained in parallel on bootstrap resamples with random feature subsets at each split, then averaged. Cuts variance dramatically and resists label noise.', lesson: 'decision-trees', aka: ['bagging'], related: ['decision-tree', 'gradient-boosting', 'bias-variance'] },
  { id: 'gradient-boosting', term: 'Gradient Boosted Trees (GBT)', short: 'An ensemble that trains shallow trees sequentially, each fitting the remaining residuals (negative loss gradients) of the ensemble so far. Dominates structured tabular data (XGBoost, LightGBM), but needs shrinkage and early stopping to avoid overfitting noise.', lesson: 'decision-trees', aka: ['XGBoost', 'LightGBM', 'GBDT', 'boosting'], related: ['decision-tree', 'random-forest'] },
  { id: 'kmeans', term: 'k-Means clustering', short: 'An unsupervised algorithm that partitions unlabelled data into k clusters by alternating two steps (Lloyd’s algorithm): assign each point to its nearest centroid, then move each centroid to the mean of its assigned points. Minimises within-cluster squared distance (inertia).', lesson: 'clustering-pca', aka: ['Lloyd’s algorithm', 'inertia'], related: ['kmeans-pp', 'silhouette-score', 'feature-scaling'] },
  { id: 'kmeans-pp', term: 'k-Means++', short: 'A smart seeding scheme for k-Means: pick the first centroid uniformly at random, then draw each subsequent centroid with probability proportional to its squared distance D(x)² from the nearest already-chosen centroid. Spreads starting centroids apart to avoid local minima.', lesson: 'clustering-pca', related: ['kmeans'] },
  { id: 'silhouette-score', term: 'Silhouette score', short: 'A cluster-quality score in [−1, +1] measuring how much closer each point is to its own cluster (a) than to the nearest neighbouring cluster (b): s = (b − a) / max(a, b). High values indicate tight, well-separated clusters.', lesson: 'clustering-pca', related: ['kmeans'] },
  { id: 'pca', term: 'Principal Component Analysis (PCA)', short: 'An unsupervised linear projection that finds orthogonal directions (eigenvectors of the covariance matrix) capturing maximum variance — equivalently, minimising squared reconstruction error by Pythagoras. Sensitive to feature scaling.', lesson: 'clustering-pca', aka: ['principal components', 'dimensionality reduction'], related: ['feature-scaling', 'variance'] },
  { id: 'image-tensor', term: 'Image tensor (NCHW / NHWC)', short: 'A multi-dimensional numeric array holding image pixels: (H, W, C) for a single image or (N, C, H, W) for a PyTorch batch of N images with C channels (3 for RGB, 1 for grayscale). Memory scales as N·C·H·W·bytes.', lesson: 'images-as-tensors', aka: ['NCHW', 'NHWC', 'pixel grid'], related: ['tensor', 'colour-space'] },
  { id: 'luminance', term: 'Luminance (Rec. 709)', short: 'Perceived brightness computed from RGB using human cone sensitivity weights: Y = 0.2126 R + 0.7152 G + 0.0722 B. Weights green ~9.9× heavier than blue, unlike naive (R+G+B)/3.', lesson: 'images-as-tensors', aka: ['grayscale', 'luma'], related: ['colour-space', 'image-tensor'] },
  { id: 'colour-space', term: 'Colour space (RGB vs HSV)', short: 'A coordinate system for representing colour. RGB mixes red, green, and blue light (sensitive to overall brightness changes); HSV separates Hue (colour angle), Saturation, and Value (brightness) so Hue stays invariant under uniform shadows.', lesson: 'images-as-tensors', aka: ['HSV', 'RGB', 'chromaticity'], related: ['luminance', 'image-tensor'] },
  { id: 'aliasing', term: 'Spatial aliasing', short: 'Visual artefacts (fake solid blocks or moiré stripes) caused by subsampling an image faster than its fine detail (e.g. img[::2, ::2] on a 1-px checkerboard) without low-pass filtering or box averaging first.', lesson: 'images-as-tensors', aka: ['moiré', 'anti-aliasing'], related: ['image-tensor'] },
  { id: 'convolution', term: '2D Convolution (cross-correlation)', short: 'Sliding a small shared weight grid (kernel) across every patch of an image and taking element-wise dot products to build a feature map. Cuts parameters by millions compared to a dense layer.', lesson: 'convolution', aka: ['Conv2d', 'cross-correlation'], related: ['kernel', 'padding-stride', 'translation-equivariance'] },
  { id: 'kernel', term: 'Convolution kernel (filter)', short: 'A tiny K×K (or K×K×C_in) weight grid scanned across an image. Weights summing to 0 detect edges and changes (Sobel, Laplacian); weights summing to 1 blur or sharpen. In CNNs, kernel weights are learned by backpropagation.', lesson: 'convolution', aka: ['filter', 'Sobel filter'], related: ['convolution', 'padding-stride'] },
  { id: 'padding-stride', term: 'Padding and stride', short: 'Padding P wraps zeros around an image border so spatial size does not collapse; stride S steps the kernel S pixels between stops. Output size is floor((H + 2P − K)/S) + 1.', lesson: 'convolution', aka: ['same padding', 'valid padding'], related: ['convolution'] },
  { id: 'translation-equivariance', term: 'Translation equivariance', short: 'The property that shifting an input image by (Δr, Δc) shifts its convolution feature map by the exact same (Δr, Δc) with identical activation values — guaranteed by sharing one kernel across all spatial positions.', lesson: 'convolution', aka: ['shift equivariance', 'weight sharing'], related: ['convolution'] },
  { id: 'cnn', term: 'Convolutional Neural Network (CNN)', short: 'A neural architecture that stacks multi-channel convolutions, nonlinearities (ReLU), and pooling/striding so early layers detect edges, middle layers detect parts, and deep layers classify whole objects with shift invariance.', lesson: 'cnns', aka: ['ConvNet'], related: ['convolution', 'receptive-field', 'pooling'] },
  { id: 'receptive-field', term: 'Receptive field', short: 'The width (in input-image pixels) of the patch that can influence a single neuron in layer ℓ. Grows via r_ℓ = r_{ℓ−1} + (k_ℓ − 1)·j_{ℓ−1} where jump j_ℓ multiplies by each layer’s stride.', lesson: 'cnns', related: ['cnn', 'convolution', 'pooling'] },
  { id: 'pooling', term: 'Pooling (Max & Average)', short: 'Spatial downsampling over small non-overlapping blocks (typically 2×2 stride 2). Doubles effective stride (growing receptive fields rapidly) and absorbs small 1-pixel shifts to build local translation invariance.', lesson: 'cnns', aka: ['MaxPool', 'AvgPool'], related: ['cnn', 'receptive-field', 'global-average-pooling'] },
  { id: 'global-average-pooling', term: 'Global Average Pooling (GAP)', short: 'Collapsing each feature-map channel (H, W) down to a single scalar spatial average before the final linear classifier. Cuts ImageNet classifier-head parameters >200× compared to VGG’s dense Flatten head.', lesson: 'cnns', aka: ['GAP'], related: ['pooling', 'cnn'] },
  { id: 'iou', term: 'Intersection over Union (IoU)', short: 'Bounding-box overlap metric: Area(A ∩ B) / Area(A ∪ B), ranging from 0 (disjoint) to 1 (identical). Because IoU is scale-normalised, small distant objects lose far more IoU from a fixed pixel error than large objects.', lesson: 'object-detection', aka: ['Jaccard index'], related: ['nms', 'map'] },
  { id: 'nms', term: 'Non-Maximum Suppression (NMS)', short: 'Post-processing algorithm that picks the highest-confidence bounding box and suppresses (Hard NMS) or smoothly decays (Soft-NMS) overlapping same-class boxes above an IoU threshold to remove duplicate detections.', lesson: 'object-detection', aka: ['Soft-NMS'], related: ['iou', 'map'] },
  { id: 'map', term: 'Mean Average Precision (mAP)', short: 'Standard object-detection benchmark metric: area under the interpolated Precision–Recall curve (AP) with strict 1-to-1 ground-truth matching, averaged across classes and (in COCO mAP@[.50:.95]) across 10 IoU thresholds from 0.50 to 0.95.', lesson: 'object-detection', aka: ['AP50', 'AP75', 'COCO mAP'], related: ['iou', 'nms', 'precision-recall'] },
  { id: 'one-hot-encoding', term: 'One-hot encoding', short: 'Representing category ID i out of V choices as a length-V vector with a single 1 at index i and zeros everywhere else. Avoids fake linear ordering, but makes every distinct pair orthogonal (cosine similarity 0) with zero synonym transfer.', lesson: 'one-hot-vs-dense', aka: ['one-hot vector'], related: ['embedding', 'embedding-table'] },
  { id: 'embedding-table', term: 'Embedding table (nn.Embedding)', short: 'A learnable V×d weight matrix E where looking up token ID i returns row E[i] in O(1) — mathematically identical to the one-hot matrix product e_iᵀ E while skipping 99.999% zero multiplications.', lesson: 'one-hot-vs-dense', aka: ['lookup table'], related: ['embedding', 'one-hot-encoding'] },
  { id: 'distributional-hypothesis', term: 'Distributional hypothesis', short: 'J. R. Firth’s principle (“you shall know a word by the company it keeps”): words that occur in similar surrounding contexts tend to have similar meanings, allowing embeddings to be learned from raw unlabelled text.', lesson: 'word-embeddings', related: ['word2vec', 'embedding'] },
  { id: 'word2vec', term: 'Word2Vec (Skip-Gram)', short: 'A self-supervised model that learns dense static word embeddings by training each centre word’s vector to predict its neighbouring context words, inducing semantic clusters and linear analogies (king − man + woman ≈ queen).', lesson: 'word-embeddings', aka: ['Skip-Gram', 'CBOW', 'GloVe'], related: ['distributional-hypothesis', 'negative-sampling', 'embedding'] },
  { id: 'negative-sampling', term: 'Negative sampling (SGNS)', short: 'Replacing an expensive V-way softmax with 1 + K binary logistic classifiers: pull the true neighbouring word together and push K randomly drawn noise words apart. Cuts dot products by >16,000× and prevents embedding collapse.', lesson: 'word-embeddings', aka: ['SGNS'], related: ['word2vec'] },
  { id: 'ann-search', term: 'Approximate Nearest Neighbour (ANN) search', short: 'Algorithms (IVF, LSH, HNSW) that search millions of high-dimensional embeddings in milliseconds by skipping most of the database, trading a small fraction of recall for 10×–100× speedup.', lesson: 'similarity-search', aka: ['ANN', 'vector search', 'HNSW'], related: ['ivf-index', 'lsh', 'product-quantization'] },
  { id: 'ivf-index', term: 'Inverted File Index (IVF)', short: 'An ANN index that clusters vectors with k-Means into nlist Voronoi buckets at build time, then opens only the nprobe closest buckets at query time. Adapts to real cluster geometry.', lesson: 'similarity-search', aka: ['IVF', 'nprobe'], related: ['ann-search', 'kmeans', 'lsh'] },
  { id: 'lsh', term: 'Locality-Sensitive Hashing (LSH)', short: 'Hashing similar vectors into the same bucket with high probability — e.g., SimHash uses b random hyperplanes per table so two vectors at angle θ agree per bit with probability 1 − θ/π.', lesson: 'similarity-search', aka: ['SimHash', 'random hyperplanes'], related: ['ann-search', 'ivf-index'] },
  { id: 'product-quantization', term: 'Product Quantisation (PQ)', short: 'Compressing high-dimensional embeddings by splitting each vector into M sub-vectors and replacing each chunk with a 1-byte k-Means centroid ID (e.g., 1,536D FP32 → 64 bytes = 96× smaller).', lesson: 'similarity-search', aka: ['PQ', 'vector compression'], related: ['ann-search', 'quantization'] },
  { id: 'contrastive-learning', term: 'Contrastive learning', short: 'Self-supervised or paired representation learning (SimCLR, CLIP, sentence encoders) that trains an encoder to pull matching positive views together on the unit sphere while pushing non-matching negatives apart.', lesson: 'contrastive-learning', aka: ['SimCLR', 'CLIP'], related: ['infonce', 'alignment-uniformity', 'embedding'] },
  { id: 'infonce', term: 'InfoNCE loss', short: 'The contrastive cross-entropy objective −log(exp(cos(a, p)/τ) / Σ exp(cos(a, k)/τ)) that trains a model to pick the true positive match out of a pool of negatives, with temperature τ controlling hard-negative sharpness.', lesson: 'contrastive-learning', aka: ['NT-Xent', 'CLIP loss'], related: ['contrastive-learning', 'alignment-uniformity', 'softmax'] },
  { id: 'alignment-uniformity', term: 'Alignment & Uniformity', short: 'Wang & Isola’s geometric decomposition of contrastive representations on the unit hypersphere: Alignment pulls positive pairs close (minimising E[‖a − p‖²]), while Uniformity spreads distinct items evenly around the sphere to prevent collapse.', lesson: 'contrastive-learning', aka: ['representation collapse'], related: ['contrastive-learning', 'infonce'] },
  { id: 'rnn', term: 'Recurrent Neural Network (RNN)', short: 'A sequence architecture that reads one token at a time and updates a rolling hidden state h_t = tanh(W_x x_t + W_h h_{t−1} + b) using the exact same shared weights at every time step.', lesson: 'rnns', aka: ['Elman RNN', 'vanilla RNN'], related: ['hidden-state', 'bptt', 'gradient-clipping'] },
  { id: 'hidden-state', term: 'Hidden state (h_t)', short: 'The fixed-width memory vector carried forward from one time step to the next in an RNN, summarising all tokens seen up to step t.', lesson: 'rnns', aka: ['recurrent state'], related: ['rnn', 'bptt'] },
  { id: 'bptt', term: 'Backpropagation Through Time (BPTT)', short: 'Training an RNN by unrolling it across T time steps and running ordinary backprop right-to-left, summing the gradients on the shared weights across all steps. Truncated BPTT caps the backward window at K steps to save activation RAM.', lesson: 'rnns', aka: ['Truncated BPTT', 'TBPTT'], related: ['rnn', 'backpropagation', 'vanishing-gradients'] },
  { id: 'gradient-clipping', term: 'Gradient-norm clipping', short: 'Rescaling the entire gradient vector g ← g · c / ‖g‖₂ whenever its L2 norm exceeds threshold c. Preserves the downhill direction while stopping exploding recurrent cliffs from catapulting weights to infinity; cannot fix vanishing gradients.', lesson: 'rnns', aka: ['clip_grad_norm_'], related: ['rnn', 'bptt', 'vanishing-gradients'] },
  { id: 'lstm', term: 'Long Short-Term Memory (LSTM)', short: 'A gated recurrent cell with an additive cell-state highway c_t = f_t ⊙ c_{t−1} + i_t ⊙ c̃_t controlled by forget, input, and output gates. Lets gradients travel across long sequences without repeatedly multiplying by W_hᵀ.', lesson: 'lstms-grus', aka: ['LSTM', 'Constant Error Carousel'], related: ['gru', 'forget-gate', 'rnn'] },
  { id: 'gru', term: 'Gated Recurrent Unit (GRU)', short: 'A streamlined gated recurrent cell that merges cell and hidden state into one vector and ties forget + input into a single update gate z_t, saving 25% of parameters (3× vs LSTM’s 4×) while preserving an additive highway.', lesson: 'lstms-grus', aka: ['GRU'], related: ['lstm', 'rnn'] },
  { id: 'forget-gate', term: 'Forget gate (and bias trick)', short: 'The LSTM gate f_t = σ(W_f[x_t, h_{t−1}] + b_f) ∈ (0, 1) deciding how much of c_{t−1} survives each step. Initialising b_f = +2 or +3 starts f_t ≈ 0.9 so 25-step gradients stay alive instead of vanishing as 0.5²⁴.', lesson: 'lstms-grus', aka: ['forget-gate bias'], related: ['lstm', 'vanishing-gradients'] },
  { id: 'seq2seq', term: 'Sequence-to-Sequence (Seq2Seq)', short: 'Mapping a variable-length input sequence (such as an English sentence) to a variable-length output sequence (such as a French translation) using an Encoder–Decoder architecture.', lesson: 'seq2seq-attention', aka: ['Seq2Seq'], related: ['encoder-decoder', 'cross-attention'] },
  { id: 'encoder-decoder', term: 'Encoder–Decoder architecture', short: 'A two-network design where an encoder reads the source sequence into hidden representations and a decoder generates the target sequence token by token. Without attention, squeezing the whole input into one fixed vector creates an information bottleneck.', lesson: 'seq2seq-attention', aka: ['fixed-vector bottleneck'], related: ['seq2seq', 'cross-attention', 'lstm'] },
  { id: 'cross-attention', term: 'Cross-attention (Bahdanau & Luong)', short: 'Letting a decoder at step t compute softmax alignment weights α_{t,s} over all S encoder states h_1…h_S and blend a custom context vector c_t = Σ α_{t,s} h_s. Breaks the fixed-vector bottleneck and handles word reordering effortlessly.', lesson: 'seq2seq-attention', aka: ['Bahdanau attention', 'Luong attention', 'additive attention'], related: ['attention', 'encoder-decoder', 'seq2seq'] },
  { id: 'svm', term: 'Support Vector Machine (SVM)', short: 'A convex classifier that separates classes with the widest possible empty street (width 2/‖w‖), optionally allowing hinge-loss slack controlled by C and curved boundaries via the kernel trick.', lesson: 'svm', aka: ['SVM', 'max-margin classifier'], related: ['support-vector', 'margin', 'kernel-trick'] },
  { id: 'support-vector', term: 'Support vector', short: 'One of the few training points lying on (or inside) an SVM’s margin gutters. Only support vectors determine the boundary; moving non-support points behind their gutter leaves the street unchanged.', lesson: 'svm', related: ['svm', 'margin'] },
  { id: 'margin', term: 'Margin (street width)', short: 'The empty perpendicular gap separating two classes around a linear decision boundary. With gutters at w·x + b = ±1, the full street width is 2/‖w‖, so maximising the margin means minimising ½‖w‖².', lesson: 'svm', aka: ['maximum margin'], related: ['svm', 'support-vector'] },
  { id: 'kernel-trick', term: 'Kernel trick', short: 'Replacing dot products xᵢ·xⱼ in a dual SVM with a similarity function k(xᵢ, xⱼ) = φ(xᵢ)·φ(xⱼ) so a flat hyperplane in a higher-dimensional feature space draws curved boundaries in the input space without storing φ(x).', lesson: 'svm', aka: ['kernel method', 'RBF kernel'], related: ['svm', 'feature-engineering'] },
  { id: 'moe', term: 'Mixture of experts (MoE)', short: 'A layer made of several small networks (experts) plus a router that sends each token to only a few of them. The model holds every expert’s weights but each token pays the arithmetic of just the chosen ones.', lesson: 'moe', aka: ['mixture of experts', 'sparse MoE', 'expert', 'experts', 'router'], related: ['router-collapse', 'load-balancing-loss'] },
  { id: 'router-collapse', term: 'Router collapse', short: 'When a mixture-of-experts router keeps sending most tokens to a few experts and starves the rest: experts that get no tokens get no gradient, so they never improve and never win tokens back.', lesson: 'moe', aka: ['expert collapse', 'load imbalance'], related: ['moe', 'load-balancing-loss'] },
  { id: 'load-balancing-loss', term: 'Load-balancing loss', short: 'An extra term added to a mixture-of-experts loss that is smallest when tokens are spread evenly over the experts. The Switch Transformer form is α · E · Σ fᵢ Pᵢ.', lesson: 'moe', aka: ['auxiliary loss', 'aux loss', 'capacity factor'], related: ['moe', 'router-collapse'] },
  { id: 'gan', term: 'Generative Adversarial Network (GAN)', short: 'A pair of neural networks trained in an adversarial duel: a generator G(z) turns random noise into synthetic samples while a discriminator D(x) tries to tell real examples from fakes.', lesson: 'gans', aka: ['GAN', 'adversarial training'], related: ['mode-collapse', 'minimax-game', 'generative-model'] },
  { id: 'mode-collapse', term: 'Mode collapse', short: 'A GAN failure where the generator produces sharp, realistic samples from only one or a few modes of the real data while ignoring the rest, sacrificing variety to fool the discriminator easily.', lesson: 'gans', related: ['gan', 'minimax-game'] },
  { id: 'minimax-game', term: 'Minimax game', short: 'A two-player zero-sum objective min_G max_D V(D, G) where one network tries to maximise a payoff while the other tries to minimise it. In a GAN, the global equilibrium is p_G = p_data and D(x) = 0.5 everywhere.', lesson: 'gans', related: ['gan', 'mode-collapse'] },
];

export const glossaryById = Object.fromEntries(GLOSSARY.map((g) => [g.id, g]));
